-- CRM seed — real Drive CRM history into Supabase (system of record).
-- GENERATED by scripts/build-crm-seed.ts from src/app/_data/dataset.ts.
-- Do not edit by hand; edit the dataset and regenerate.
-- Idempotent: profiles matched by name, deals/leads upserted on
-- (organization_id, external_id). Requires migrations 0000–0008.
-- Apply: supabase SQL editor, or psql "$DATABASE_URL" -f supabase/seeds/crm_seed.sql
-- ============================================================================

-- 1) Team identities -------------------------------------------------------
do $$
declare
  org constant uuid := '6a32be59-155d-4662-9058-3a74fb2b6872';
  a jsonb;
  v_id uuid;
begin
  for a in select * from jsonb_array_elements($staff$[
    {"name":"Shatha Al Manthari","email":"agent.shatha@alwalaaoman.com","staff_role":"senior_advisor","status":"active","segment":"diaspora","target":350000,"ramp_end":"","exempt":false,"drive":"https://drive.google.com/drive/folders/1-r9HPvaiH-LDbd3Rv6m_Sp_PiPDvaTJB","closed_docs":"https://drive.google.com/drive/folders/1vUhUiZygkAGtVwN_-10QP_tlOJs-Cey2","vouchers":"https://drive.google.com/drive/folders/1g7OSUcaOoq3SiOt2NuvRO05TD0Gy5fkN"},
    {"name":"Yousef","email":"agent.yousef@alwalaaoman.com","staff_role":"sales_manager","status":"former","segment":"na","target":0,"ramp_end":"","exempt":false,"drive":"https://drive.google.com/drive/folders/10Fr22TuuAXL6kj3Wa3vYPj_hA3dtVqXr","closed_docs":"https://drive.google.com/drive/folders/1qvuv5qbiRMZBXM_A_H3g4Pszo4kGenwN","vouchers":"https://drive.google.com/drive/folders/1J8ZM4_zrGDviuZdvD_2gubTmFOQnRlwZ"},
    {"name":"Alex Showran","email":"agent.alex@alwalaaoman.com","staff_role":"advisor","status":"active","segment":"resident","target":250000,"ramp_end":"","exempt":false,"drive":"https://drive.google.com/drive/folders/1BJMCIFLLcqqhv4IpaJxovcgiGHeIBlJU","closed_docs":"https://drive.google.com/drive/folders/1-XxmHUPyhzEGY5yfJ7t93H7-85NEkH_6","vouchers":"https://drive.google.com/drive/folders/1MoLzIKfHdJ54E-qyyxwKaGWoAsvzOuit"},
    {"name":"Pasha","email":"agent.pasha@alwalaaoman.com","staff_role":"advisor","status":"active","segment":"resident","target":250000,"ramp_end":"","exempt":false,"drive":"https://drive.google.com/drive/folders/1zBD-0lDQxZgwt0m74aNOgk16A8AyA6S9","closed_docs":"https://drive.google.com/drive/folders/1GlZNvJ15TVhicjlQAzSlueVzHoFxFo1a","vouchers":"https://drive.google.com/drive/folders/1_RXKortsifhp3GJRB5TCZMxD7mSjJMNJ"},
    {"name":"Wesam Zeno","email":"agent.wesam@alwalaaoman.com","staff_role":"advisor","status":"active","segment":"resident","target":250000,"ramp_end":"","exempt":false,"drive":"https://drive.google.com/drive/folders/18jh5WBpXifLf-5bxPdqRZQxHQW5FCDoB","closed_docs":"https://drive.google.com/drive/folders/1Hort5_HjU6jrhUkWMS7qvE6dvBsyPaqj","vouchers":"https://drive.google.com/drive/folders/14j4h7-9EU0Akbr9FGluwi377kmKEGv26"},
    {"name":"Khalid","email":"agent.khalid@alwalaaoman.com","staff_role":"advisor","status":"active","segment":"resident","target":120000,"ramp_end":"2026-09-01","exempt":false,"drive":"","closed_docs":"","vouchers":""},
    {"name":"Tariq","email":"agent.tariq@alwalaaoman.com","staff_role":"advisor","status":"active","segment":"na","target":0,"ramp_end":"","exempt":true,"drive":"https://drive.google.com/drive/folders/1ZxXvWfcyFh7vE-jLAJ83s-u-Ac9khtcz","closed_docs":"","vouchers":""},
    {"name":"Abeer Al Wardi","email":"agent.abeer@alwalaaoman.com","staff_role":"marketing_manager","status":"active","segment":"na","target":0,"ramp_end":"","exempt":false,"drive":"https://drive.google.com/drive/folders/1QlDo9hkF8WY2t8_xUHiZ2axf8v7K8P4C","closed_docs":"","vouchers":""}
  ]$staff$::jsonb) loop
    -- Reuse the existing profile when the person is already in the system.
    select p.id into v_id from profiles p
      where p.organization_id = org and lower(p.full_name) = lower(a->>'name')
      limit 1;
    if v_id is null then
      select u.id into v_id from auth.users u where lower(u.email) = lower(a->>'email');
    end if;
    if v_id is null then
      v_id := gen_random_uuid();
      insert into auth.users (instance_id, id, aud, role, email, email_confirmed_at,
                              raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
      values ('00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated',
              a->>'email', now(),
              '{"provider":"email","providers":["email"]}'::jsonb,
              jsonb_build_object('name', a->>'name'), now(), now());
    end if;
    insert into profiles (id, organization_id, full_name, role)
    values (v_id, org, a->>'name', 'member')
    on conflict (id) do update set organization_id = excluded.organization_id,
                                   full_name = excluded.full_name;
    insert into staff_profiles (id, organization_id, role, status, segment,
                                monthly_target_omr, ramp_end_date, exempt_from_at_risk,
                                drive_folder_url, closed_docs_url, vouchers_url)
    values (v_id, org, (a->>'staff_role')::staff_role, (a->>'status')::staff_status,
            (a->>'segment')::agent_segment, (a->>'target')::numeric,
            nullif(a->>'ramp_end','')::date, (a->>'exempt')::boolean,
            nullif(a->>'drive',''), nullif(a->>'closed_docs',''), nullif(a->>'vouchers',''))
    on conflict (id) do update set
      role = excluded.role, status = excluded.status, segment = excluded.segment,
      monthly_target_omr = excluded.monthly_target_omr,
      ramp_end_date = excluded.ramp_end_date,
      exempt_from_at_risk = excluded.exempt_from_at_risk,
      drive_folder_url = excluded.drive_folder_url,
      closed_docs_url = excluded.closed_docs_url,
      vouchers_url = excluded.vouchers_url;
  end loop;
end $$;

